// TH16 v1.00a st06bs.ecl.txt Boss5 (Stage 6 final boss, 5th nonspell), source lines 549-619.
// The source sub runs on the boss after BossCard4 and loops moveRand + Boss5_at until HP/timeout.
// Independent shell: the boss carries phase/spell, so the phase pattern tree is stopped by the
// segment timer. Entry movement zeroing and position come from the boss common entry (0,128).

const TIME_LIMIT: int = 2524;    // 120 shell buffer + 2400 source window + 4 startup margin
const OPENING_BUFFER: int = 120;

const TH16_KUNAI: int = 496;     // source etSprite(0, 9, 4); base radius 2.39999
const BULLET_COLOR: int = 4;

// Boss5_at: %B starts at 0 and advances by +-3.883222 rad (0.618034 turn) after each etOn.
const SPIN_LEFT: int = -40503;   // -3.883222 rad in BAM
const SPIN_RIGHT: int = 40503;

const SPAWN_DIST: fx = 22fx;     // etDist(24) minus ANIM a=1 retraction 4*0.5

// Boss5_at EX: etEx VELTIME a=60 r=4.0 s=-999999 (keep own angle), configured speed 0.5.
// Fixed-direction scalar ramp from 0.5 to 4.0 over 60 frames; then keep 4.0.
xformdef TH16_VELTIME_RAMP {
    // @N is a post-delay: the accelerating op holds 60 frames, then gravity is zeroed.
    @60 set_gravity(at_spawn(0.0583333fx * cos($self_angle)),
                    at_spawn(0.0583333fx * sin($self_angle)));
    set_gravity(0fx, 0fx);
}

// moveRand (412) target recipe from transcribe/th16/movement.md. Boss-owned slots:
// self_int(0)=next step count, self_int(1)=frames, self_fx(0/1)=logical cos/sin,
// self_fx(2)=start speed. No other user of these slots in this card.
sub motion_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var frames: int = self_int(1);
    var v: fx = 0fx;
    if k < frames {
        v = self_fx(2) * ((frames - k) as fx) / (frames as fx);
    }
    var nx: fx = $self_x + self_fx(0) * v;
    var ny: fx = $self_y + self_fx(1) * v;
    if nx < -120fx { nx = -120fx; }
    if nx > 120fx { nx = 120fx; }
    if ny < 112fx { ny = 112fx; }
    if ny > 144fx { ny = 144fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub motion_begin(a: angle, frames: int, speed: fx) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    set_self_int(1, frames);
    set_self_fx(2, speed);
    motion_step();
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        motion_step();
    }
}

// moveRand(412) direction selection. moveLimit(0,128,240,32) actual bounds are
// x[-120,120], y[112,144]; the selection inner zone is center +- width/4, height/4,
// i.e. x +-60 and y[120,136].
sub boss5_move_rand(frames: int, speed: fx) {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -60fx {
        a = r / 3;
    } else if $self_x > 60fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 120fx {
        if a < 0 { a = -a; }
    } else if $self_y > 136fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    motion_begin(a as angle, frames, speed);
}

// Boss5_at: etNew(0), etAim(0,3) fixed ring, etSprite(0,9,4), rank count, etSpeed(0,0.5,0.2),
// etEx ANIM a=1 (birth stage omitted) + VELTIME, etDist(24); 241 outer frames, D etOn per
// frame (E/N/H=1, L=5); %B advances by the argument after every etOn.
sub boss5_burst(step: int) {
    sh_reset(0);
    sh_sprite(0, TH16_KUNAI, BULLET_COLOR);
    sh_ring(0, 1);
    var n: int = 1;
    if global(GVAR_RANK) == RANK_NORMAL { n = 3; }
    if global(GVAR_RANK) == RANK_HARD { n = 4; }
    sh_count(0, n, 1);
    sh_speed(0, 0.5fx, 0fx);
    sh_dist(0, SPAWN_DIST);
    sh_xform(0, TH16_VELTIME_RAMP);

    var shots: int = 1;
    if global(GVAR_RANK) == RANK_LUNATIC { shots = 5; }

    var b: int = 0;
    var c: int = 241;
    while c > 0 {
        c = c - 1;
        for j in 0..shots {
            sh_angle(0, b as angle, 0deg);
            sh_fire(0);
            b = b + step;
        }
        card_wait(1);
    }
}

async sub boss5_attack() {
    wait(OPENING_BUFFER);            // shell buffer, before the source segment starts
    // Source opening: wait(60); wait(60); wait(60) with anmSelect/anmPlay/playSound/fog omitted.
    wait(60);
    wait(60);
    wait(60);
    loop {
        boss5_move_rand(240, 0.5fx);
        boss5_burst(SPIN_LEFT);
        boss5_move_rand(60, 1.9fx);
        card_wait(60);
        boss5_move_rand(240, 0.5fx);
        boss5_burst(SPIN_RIGHT);
        boss5_move_rand(60, 1.9fx);
        card_wait(60);
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(25fx);                // Boss(): setHitbox(50,50) -> radius 25
    set_hurtbox(28fx);               // Boss(): setHurtbox(56,56) -> radius 28
    phase_begin(0, boss5_attack, TIME_LIMIT, 0);
    wait_spell();
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 19200, 0, 0, 0, boss_main);   // lifeSet(19200)
    loop { wait(600); }
}
